from pathlib import Path
import inspect,py_compile
from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import persistent_profit_runtime as p

ROOT=Path.cwd()
SUB=ROOT/"qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot"
BASE=SUB/"qarb_026b_forward_horizon_paper_pnl.py"
if not BASE.is_file():
    raise SystemExit("[FAIL] dependency missing: "+str(BASE))

serve_src=inspect.getsource(p.serve)
for marker in ("SimulationLane(root,state)","sim_lane.worker(stop)","_initial_scan(state,c,sim_lane)","_process_event(state,ev,c,sim_lane)"):
    if marker not in serve_src:
        raise SystemExit("[FAIL] exact 022D serve contract missing: "+marker)

MOD=SUB/"qarb_026f_exact_horizon_scheduler.py"
MOD.write_text('from __future__ import annotations\nimport asyncio,json,os,time\nfrom pathlib import Path\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import persistent_profit_runtime as p\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import qarb_026b_forward_horizon_paper_pnl as base\n\nEXECUTION_AUTHORITY=False\nPAPER_ONLY=True\nTICK_SECONDS=0.05\n_WARNED_AT=0.0\n\ndef safe_persist(book):\n    global _WARNED_AT\n    path=book.root/base.STATE_REL\n    path.parent.mkdir(parents=True,exist_ok=True)\n    text=json.dumps(book.summary(),sort_keys=True,indent=2)\n    tmp=path.with_name(path.name+".%d.%d.tmp"%(os.getpid(),time.time_ns()))\n    try:\n        tmp.write_text(text,encoding="utf-8")\n        for i in range(5):\n            try:\n                os.replace(tmp,path)\n                return True\n            except PermissionError:\n                time.sleep(.05*(i+1))\n        try:\n            path.write_text(text,encoding="utf-8")\n            return True\n        except PermissionError:\n            now=time.monotonic()\n            if now-_WARNED_AT>15:\n                print("[PAPER_STATE_WARN] scoreboard write blocked; runtime continues",flush=True)\n                _WARNED_AT=now\n            return False\n    finally:\n        try: tmp.unlink(missing_ok=True)\n        except Exception: pass\n\ndef _patched_persist(self):\n    safe_persist(self)\n\nbase.Book.persist=_patched_persist\n\nclass PaperSimulationLane:\n    def __init__(self,root,state):\n        self.root=Path(root)\n        self.state=state\n        self.book=base.Book(root,state["landing"])\n        self.pairs={x.token:x for x in state.get("pairs",())}\n        self.entries=0\n        self.unsupported=0\n\n        # Compatibility attributes read by the untouched persistent_profit_runtime.serve().\n        self.attempts=0\n        self.profitable=0\n        self.best=None\n        self.failures=0\n        self.drops=0\n\n    def submit(self,r):\n        self.attempts+=1\n        buy=r.get("buy_venue");sell=r.get("sell_venue")\n        if buy=="PUMPSWAP" and sell=="METEORA_DLMM":\n            direction="PUMP_TO_METEORA"\n        elif buy=="METEORA_DLMM" and sell=="PUMPSWAP":\n            direction="METEORA_TO_PUMP"\n        else:\n            self.unsupported+=1\n            return\n\n        pair=self.pairs.get(r.get("token"))\n        if pair is None:\n            self.unsupported+=1\n            return\n\n        d={"direction":direction,"size_sol":float(r["size_sol"]),\n           "net_sol":float(r["net_sol"]),"net_bps":float(r["net_bps"])}\n        pos=self.book.enter(pair,d,time.monotonic())\n        if pos is not None:\n            self.entries+=1\n            print("[PAPER_ENTRY] token=%s buy=%s sell=%s size=%.6f quote=%+.9f SOL bps=%+.2f slot=%d"%(\n                pos.token[:10],buy,sell,pos.size_sol,pos.entry_quote_net_sol,\n                pos.entry_quote_bps,pos.entry_slot),flush=True)\n\n    def mark_due(self):\n        now=time.monotonic()\n        for pair in self.state.get("pairs",()):\n            for row in self.book.update_pair(pair,now):\n                print("[PAPER_EXIT] token=%s dir=%s size=%.6f horizon=%gs age=%.3fs lateness=%+.3fs pnl=%+.9f SOL"%(\n                    row["token"][:10],row["direction"],row["size_sol"],\n                    row["horizon_seconds"],row["actual_age_seconds"],\n                    row["actual_age_seconds"]-row["horizon_seconds"],\n                    row["paper_net_sol"]),flush=True)\n\n    async def worker(self,stop):\n        # This replaces only the old simulation worker. The original market runtime remains untouched.\n        last_score=time.monotonic()\n        while not stop.is_set():\n            self.mark_due()\n            now=time.monotonic()\n            if now-last_score>=p.HEARTBEAT_SECONDS:\n                print("[PAPER_SCORE] "+base._score_line(self.book)+\n                      " open=%d entries=%d submitted=%d unsupported=%d"%(\n                      len(self.book.open),self.entries,self.attempts,self.unsupported),flush=True)\n                last_score=now\n            try:\n                await asyncio.wait_for(stop.wait(),timeout=TICK_SECONDS)\n            except asyncio.TimeoutError:\n                pass\n        self.book.persist()\n\ndef install_lane():\n    p.SimulationLane=PaperSimulationLane\n    return p\n\ndef main(argv=None):\n    import argparse\n    ap=argparse.ArgumentParser()\n    ap.add_argument("--seconds",type=float,default=None)\n    a=ap.parse_args(argv)\n    runtime=install_lane()\n    print("[QARB-026F] UNTOUCHED 022D RUNTIME + PAPER LANE",flush=True)\n    print("[ENGINE] persistent_profit_runtime.serve unchanged",flush=True)\n    print("[HOOK] SimulationLane class only -> PaperSimulationLane",flush=True)\n    print("[CLOCK] 50ms exact-horizon scheduler",flush=True)\n    print("[STATE] Windows-safe persistence",flush=True)\n    print("[MODE] PAPER_ONLY=True execution_authority=FALSE",flush=True)\n    return asyncio.run(runtime.serve(Path.cwd(),a.seconds))\n\nif __name__=="__main__":\n    main()\n',encoding="utf-8")
TEST=ROOT/"test_qarb_026f_exact_horizon_scheduler.py"
TEST.write_text('import inspect,unittest\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot import qarb_026f_exact_horizon_scheduler as q\n\nclass T(unittest.TestCase):\n    def test_original_serve_not_reimplemented(self):\n        src=inspect.getsource(q)\n        self.assertNotIn("async def serve(",src)\n        self.assertIn("runtime.serve(Path.cwd()",src)\n        print("[PASS] original persistent_profit_runtime.serve is called directly")\n\n    def test_only_lane_is_swapped(self):\n        old=q.p.SimulationLane\n        try:\n            r=q.install_lane()\n            self.assertIs(r.SimulationLane,q.PaperSimulationLane)\n        finally:\n            q.p.SimulationLane=old\n        print("[PASS] only SimulationLane class is replaced")\n\n    def test_lane_contract(self):\n        for name in ("submit","worker"):\n            self.assertTrue(hasattr(q.PaperSimulationLane,name))\n        for attr in ("attempts","profitable","best","failures","drops"):\n            self.assertIn("self."+attr,inspect.getsource(q.PaperSimulationLane.__init__))\n        print("[PASS] paper lane satisfies untouched 022D serve compatibility contract")\n\n    def test_exact_clock(self):\n        self.assertLessEqual(q.TICK_SECONDS,.05)\n        self.assertIn("mark_due",inspect.getsource(q.PaperSimulationLane.worker))\n        print("[PASS] <=50ms paper horizon scheduler lives inside replacement lane")\n\n    def test_no_execution(self):\n        self.assertTrue(q.PAPER_ONLY)\n        self.assertFalse(q.EXECUTION_AUTHORITY)\n        print("[PASS] PAPER_ONLY=True execution_authority=FALSE")\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n',encoding="utf-8")
RUN=ROOT/"run_qarb_026f_exact_horizon_scheduler.py"
RUN.write_text('from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.qarb_026f_exact_horizon_scheduler import main\nif __name__=="__main__":\n    main()\n',encoding="utf-8")

for x in (MOD,TEST,RUN):
    py_compile.compile(str(x),doraise=True)

print("[PASS] QARB-026F exact native-lane repair installed")
print("[ENGINE] persistent_profit_runtime.serve NOT reimplemented")
print("[HOOK] only SimulationLane replaced with paper lane")
print("[SIGNALS] original prepare/shards/workers/initial_scan/process_event untouched")
print("[CLOCK] 50ms forward-horizon scheduler")
